# Pandas solution:
import pandas as pd

class Solution:
    def find_expensive_cities(self, listings: pd.DataFrame) -> pd.DataFrame:
        national_avg = listings['price'].mean()
        city_avg = listings.groupby('city')['price'].mean().reset_index()
        return city_avg[city_avg['price'] > national_avg][['city']].sort_values('city')

