# Pandas alternative:
import pandas as pd

class Solution:
    def find_expensive_cities(self, listings: pd.DataFrame) -> pd.DataFrame:
        listings['nat'] = listings['price'].mean()
        g = listings.groupby('city').agg(city_avg=('price', 'mean'), nat=('nat', 'max')).reset_index()
        return g[g['city_avg'] > g['nat']][['city']].sort_values('city')

